#!/usr/bin/env python3
# BLACKWATCH Community Feed Edition — self-contained installer
import argparse,base64,hashlib,io,pathlib,subprocess,sys,tempfile,zipfile
PAYLOAD=''
SHA256='15d79f7fa5c96622c9f6eb7ed5745b6f9df95cad9e96a09b8a2d28f9176c3214'
def main():
    raw=base64.b64decode(PAYLOAD)
    if hashlib.sha256(raw).hexdigest()!=SHA256:sys.exit('Installer payload checksum mismatch')
    if '--verify' in sys.argv:
        print('BLACKWATCH Community 1.0: payload verified');return
    with tempfile.TemporaryDirectory(prefix='blackwatch-install-') as d:
        with zipfile.ZipFile(io.BytesIO(raw)) as z:
            for name in z.namelist():
                p=pathlib.PurePosixPath(name)
                if p.is_absolute() or '..' in p.parts:sys.exit('Invalid archive path')
            z.extractall(d)
        subprocess.run([sys.executable,str(pathlib.Path(d)/'install.py')]+sys.argv[1:],check=True)
if __name__=='__main__':main()
